import { test, performLogin, assertLoggedIn, assertLoginRejected, assertLoggedOut } from '../support/tathya.js';

test.use({ storageState: { cookies: [], origins: [] } });

test.describe("admin login", () => {
  test.skip(({ role }) => role !== "admin", "runs under the admin project only");

  test("admin logs in with valid credentials", { tag: ["@positive","@auth","@role:admin","@read"], annotation: [{"type":"tier","description":"positive"},{"type":"category","description":"auth"}] }, async ({ page }) => {
    await test.step("Log in as admin@example.com", () => performLogin(page, "admin@example.com", "password"));
    await test.step('Expect to be logged in', () => assertLoggedIn(page));
  });

  test("admin is rejected with a wrong password", { tag: ["@negative","@auth","@role:admin","@write"], annotation: [{"type":"tier","description":"negative"},{"type":"category","description":"auth"}] }, async ({ page }) => {
    await test.step("Log in as admin@example.com", () => performLogin(page, "admin@example.com", "password-wrong"));
    await test.step('Expect the login to be rejected', () => assertLoginRejected(page));
  });

  test("admin logs out", { tag: ["@positive","@auth","@role:admin","@write"], annotation: [{"type":"tier","description":"positive"},{"type":"category","description":"auth"},{"type":"route","description":"/dashboard"}] }, async ({ page, app }) => {
    await test.step("Log in as admin", () => app.loginAs("admin"));
    await test.step("Open /dashboard", () => page.goto("/dashboard"));
    await test.step('Log out', async () => {
      const form = page.locator("form[action$=\"/logout\"]").first();
      const submitControl = ((await form.count()) > 0 ? form.locator("button[type=\"submit\"]") : page.locator("button[type=\"submit\"]").first());
      // Logout controls usually live in a collapsed account menu; the scenario is that the session
      // ends, not the menu animation, so submit the form directly when its control is hidden.
      if (await submitControl.isVisible().catch(() => false)) await submitControl.click();
      else if ((await form.count()) > 0) await form.evaluate((element) => (element as HTMLFormElement).requestSubmit());
      else await submitControl.click({ force: true });
    });
    await test.step("Expect /dashboard to need a login again", () => assertLoggedOut(page, "/dashboard"));
  });
});

